(()=>{
 const records=window.portfolioCollection,{esc}=window.PortfolioNarrative;
 const dialog=document.createElement('dialog');dialog.className='project-reader';dialog.setAttribute('aria-labelledby','reader-title');document.body.append(dialog);
 let opener=null,oldHash='',oldOverflow='',mode='',category='All';
 const make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text)el.textContent=text;return el};
 function begin(){if(dialog.open)return;opener=document.activeElement;oldHash=location.hash.startsWith('#project-')||location.hash==='#projects'?'#work':location.hash;oldOverflow=document.documentElement.style.overflow;document.documentElement.style.overflow='hidden';window.PortfolioModalOpen=true;dialog.showModal()}
 function top(title,back=false){dialog.replaceChildren();const header=make('header','reader-top');if(back){const b=make('button','','← All work');b.type='button';b.onclick=library;header.append(b)}else header.append(make('span','',title));const close=make('button','','Close ×');close.type='button';close.onclick=()=>dialog.close();header.append(close);dialog.append(header);return header}
 function showProject(id){const item=records.find(r=>r.id===id);if(!item)return;begin();mode='project';const header=top(item.category,true),content=make('div','reader-content');const h=make('h2','',item.title);h.id='reader-title';content.append(make('p','eyebrow',item.category),h,make('p','reader-role',item.role));
  if(item.video){const player=make('div','reader-player');if(item.images?.[0]){const img=make('img');img.src=item.images[0].src;img.alt='';player.append(img)}const play=make('button','','▶ Play film');play.type='button';play.onclick=()=>{const iframe=make('iframe');iframe.title=item.title+' — video';iframe.src='https://www.youtube-nocookie.com/embed/'+item.video+'?autoplay=1&rel=0&playsinline=1';iframe.referrerPolicy='strict-origin-when-cross-origin';iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;player.replaceChildren(iframe)};player.append(play);content.append(player);const backup=make('a','reader-source','Watch on YouTube if the player is unavailable');backup.href='https://www.youtube.com/watch?v='+item.video;backup.target='_blank';backup.rel='noopener';content.append(backup)}
  if(item.note)content.append(make('p','reader-note',item.note));
  const body=make('div','reader-body');for(const[heading,text]of item.body||[]){const a=make('article');a.append(make('h3','',heading),make('p','',text));body.append(a)}content.append(body);
  if(item.images?.length){const gallery=make('div','reader-gallery');for(const pic of item.images){const f=make('figure'),img=make('img');img.src=pic.src;img.alt=pic.alt;img.loading='lazy';img.decoding='async';f.append(img,make('figcaption','',pic.alt));gallery.append(f)}content.append(gallery)}
  if(item.links?.length){const sources=make('details','reader-sources');sources.append(make('summary','','Credits and sources'));for(const[label,url]of item.links){const a=make('a','reader-source',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener';sources.append(a)}content.append(sources)}
  const cta=make('a','reader-cta','Let’s talk about what you’re building');cta.href='mailto:aaronjonesvideo@gmail.com?subject='+encodeURIComponent('Let’s talk: '+item.title)+'&body='+encodeURIComponent('Hi Aaron,\n\nI saw your work on '+item.title+'. I’m working on...\n\nCould we arrange a call?');content.append(cta);dialog.append(content);history.replaceState(null,'','#project-'+id);dialog.scrollTop=0;header.querySelector('button').focus();
 }
 function library(){begin();mode='library';const header=top('Explore the work'),content=make('div','reader-content');const h=make('h2','','The work behind the story');h.id='reader-title';content.append(h,make('p','reader-role','Follow an idea further. The people, the engineering, the result.'));
  const filters=make('div','collection-filters');filters.setAttribute('aria-label','Filter work');const grid=make('div','collection-grid');
  for(const item of records){const card=make('button','project-card');card.type='button';card.dataset.category=item.category;card.setAttribute('aria-label','Explore '+item.title);card.setAttribute('aria-haspopup','dialog');const preview=make('span','project-preview');if(item.images?.length){const img=make('img');img.src=item.images[0].src;img.alt='';img.loading='lazy';preview.append(img)}else preview.append(make('span','',item.category));card.append(preview,make('span','project-category',item.category),make('strong','',item.title),make('span','project-action',item.video?'Watch and explore ↗':'Explore ↗'));card.onclick=()=>showProject(item.id);grid.append(card)}
  function filter(){filters.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===category)));grid.querySelectorAll('.project-card').forEach(c=>c.hidden=category!=='All'&&c.dataset.category!==category)}
  for(const label of ['All',...new Set(records.map(r=>r.category))]){const b=make('button','',label);b.type='button';b.onclick=()=>{category=label;filter()};filters.append(b)}filter();content.append(filters,grid);dialog.append(content);history.replaceState(null,'','#projects');dialog.scrollTop=0;header.querySelector('button').focus();
 }
 dialog.addEventListener('close',()=>{dialog.replaceChildren();document.documentElement.style.overflow=oldOverflow;window.PortfolioModalOpen=false;history.replaceState(null,'',location.pathname+location.search+oldHash);mode='';opener?.focus({preventScroll:true});dispatchEvent(new Event('portfolio:resume'))});
 document.addEventListener('click',e=>{const button=e.target.closest('[data-project],[data-library]');if(!button)return;if(button.hasAttribute('data-library'))library();else showProject(button.dataset.project)});
 function hash(){if(location.hash==='#projects')library();else if(location.hash.startsWith('#project-'))showProject(location.hash.slice(9))}
 addEventListener('hashchange',hash);if(location.hash==='#projects'||location.hash.startsWith('#project-'))requestAnimationFrame(()=>{window.PortfolioStory?.go('work');hash()});
 window.PortfolioReader={showProject,library,close:()=>dialog.close()};
})();
